package com.netshield.models;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Synthesized diagnosis result generated by the NetShield Diagnosis Engine.
 */
public class DiagnosisOutcome {
    private final DiagnosisCategory category;
    private final String title;
    private final String summary;
    private final ConfidenceLevel confidence;
    private final Severity severity;
    private final List<DiagnosticEvidence> evidenceList;
    private final List<RecoveryAction> recoveryActions;
    private final Instant evaluatedAt;

    public DiagnosisOutcome(DiagnosisCategory category, String title, String summary,
                            ConfidenceLevel confidence, Severity severity,
                            List<DiagnosticEvidence> evidenceList,
                            List<RecoveryAction> recoveryActions) {
        this.category = category;
        this.title = title != null ? title : category.getDefaultTitle();
        this.summary = summary != null ? summary : "";
        this.confidence = confidence != null ? confidence : ConfidenceLevel.MEDIUM;
        this.severity = severity != null ? severity : category.getBaseSeverity();
        this.evidenceList = evidenceList != null ? Collections.unmodifiableList(new ArrayList<>(evidenceList)) : Collections.emptyList();
        this.recoveryActions = recoveryActions != null ? Collections.unmodifiableList(new ArrayList<>(recoveryActions)) : Collections.emptyList();
        this.evaluatedAt = Instant.now();
    }

    public DiagnosisCategory getCategory() {
        return category;
    }

    public String getTitle() {
        return title;
    }

    public String getSummary() {
        return summary;
    }

    public ConfidenceLevel getConfidence() {
        return confidence;
    }

    public Severity getSeverity() {
        return severity;
    }

    public List<DiagnosticEvidence> getEvidenceList() {
        return evidenceList;
    }

    public List<RecoveryAction> getRecoveryActions() {
        return recoveryActions;
    }

    public Instant getEvaluatedAt() {
        return evaluatedAt;
    }
}
